package store

import (
	"context"
	"errors"

	"github.com/jackc/pgx/v5"

	"github.com/ctlplne/probectl/internal/entity"
	"github.com/ctlplne/probectl/internal/tenancy"
)

// BGPRoutingBinding is operator configuration. Its ID is always generated by
// the writer; no protocol frame or caller-selected UUID supplies authority.
type BGPRoutingBinding = routingSourceBinding

// BGPRoutingBindingManifest is one complete, epoch-conditional replacement.
// A nil manifest means legacy strict global configuration; an explicit empty
// bindings array withdraws all selectors and never restores that fallback.
type BGPRoutingBindingManifest = routingSourceManifest

// ErrBGPRoutingBindingConflict means the source changed since the readback.
var ErrBGPRoutingBindingConflict = errRoutingBindingConflict

type BGPRoutingBindingConfiguration struct {
	CollectorAgentID string                     `json:"collector_agent_id"`
	SourceRef        string                     `json:"source_ref"`
	ContextID        string                     `json:"context_id"`
	RouterID         string                     `json:"router_id"`
	Manifest         *BGPRoutingBindingManifest `json:"manifest"`
}

// RoutingContextAuthorizer checks current stored context policy attributes.
// It executes within the caller's existing tenant transaction and must neither
// acquire another database connection nor perform an outward operation.
type RoutingContextAuthorizer func(context.Context, entity.ContextRecord) error

// BindingsInScope returns a complete configuration only after policy approval
// of its base and every current target. The caller owns the tenant read snapshot.
func (BGPRouting) BindingsInScope(ctx context.Context, sc tenancy.Scope, collector, origin string, budget BGPRoutingBudget, authorize RoutingContextAuthorizer) (BGPRoutingBindingConfiguration, error) {
	config, err := loadRoutingSourceConfiguration(ctx, sc, collector, origin, budget)
	if err != nil {
		return BGPRoutingBindingConfiguration{}, err
	}
	if err := authorizeRoutingContexts(ctx, sc, config, nil, false, authorize); err != nil {
		return BGPRoutingBindingConfiguration{}, err
	}
	return publicRoutingConfiguration(config), nil
}

// ReplaceBindingsInScope requires the caller's fenced tenant write transaction
// and audit append. The tenant account lock precedes the configuration read,
// so another routing writer cannot replace the current targets while policy is
// checked. The lower writer locks/rechecks the current source and target births.
func (BGPRouting) ReplaceBindingsInScope(ctx context.Context, sc tenancy.Scope, collector, origin, baseContext, ifMatch string,
	bindings []BGPRoutingBinding, budget BGPRoutingBudget, authorize RoutingContextAuthorizer) (BGPRoutingBindingConfiguration, error) {
	if err := routingConfigurationScope(ctx, sc); err != nil {
		return BGPRoutingBindingConfiguration{}, err
	}
	prepared, err := prepareRoutingBindings(ctx, bindings, budget)
	if err != nil {
		return BGPRoutingBindingConfiguration{}, err
	}
	if err := lockBGPRoutingState(ctx, sc); err != nil {
		return BGPRoutingBindingConfiguration{}, err
	}
	config, err := loadRoutingSourceConfiguration(ctx, sc, collector, origin, budget)
	if err != nil {
		return BGPRoutingBindingConfiguration{}, err
	}
	if config.BaseContextID != baseContext {
		return BGPRoutingBindingConfiguration{}, entity.ErrScopeMismatch
	}
	if err := authorizeRoutingContexts(ctx, sc, config, prepared, true, authorize); err != nil {
		return BGPRoutingBindingConfiguration{}, err
	}
	manifest, err := putRoutingBindings(ctx, sc, collector, origin, baseContext, ifMatch, prepared, budget)
	if err != nil {
		return BGPRoutingBindingConfiguration{}, err
	}
	config.Manifest = &manifest
	return publicRoutingConfiguration(config), nil
}

func routingConfigurationScope(ctx context.Context, sc tenancy.Scope) error {
	tenant, ok := tenancy.FromContext(ctx)
	if !ok || tenant != sc.Tenant {
		return entity.ErrScopeMismatch
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if sc.Q == nil {
		return ErrBGPRoutingSourceUnavailable
	}
	return nil
}

func authorizeRoutingContexts(ctx context.Context, sc tenancy.Scope, config routingSourceConfiguration, replacement []BGPRoutingBinding, retiring bool, authorize RoutingContextAuthorizer) error {
	if err := routingConfigurationScope(ctx, sc); err != nil {
		return err
	}
	if authorize == nil || config.TenantID != sc.Tenant.String() {
		return entity.ErrScopeMismatch
	}
	contexts := map[string]bool{config.BaseContextID: true}
	if config.Manifest != nil {
		for _, binding := range config.Manifest.Bindings {
			if _, exists := contexts[binding.ContextID]; !exists {
				contexts[binding.ContextID] = !retiring
			}
		}
	}
	for _, binding := range replacement {
		contexts[binding.ContextID] = true
	}
	for id, required := range contexts {
		record, err := (&EntityRegistry{}).GetEntityContextInScope(ctx, sc, id)
		// A removed context has no current policy attributes or routing
		// authority. An authorized base owner may withdraw that stale reference;
		// a replacement target and readback still require a current owned row.
		if !required && errors.Is(err, pgx.ErrNoRows) {
			continue
		}
		if err != nil {
			return err
		}
		if err := authorize(ctx, record); err != nil {
			return err
		}
	}
	return nil
}

func publicRoutingConfiguration(config routingSourceConfiguration) BGPRoutingBindingConfiguration {
	return BGPRoutingBindingConfiguration{CollectorAgentID: config.CollectorID, SourceRef: config.OriginID,
		ContextID: config.BaseContextID, RouterID: config.BaseRouterID, Manifest: config.Manifest}
}
